"""query_library/marketing_v3.py — 50 consultas adicionales de Marketing (v3)."""
from backend.modules.db_simulator.query_library.builder import q
QUERIES_MARKETING_V3: list = [
    q("mx3_001","Clientes captados por mes","¿Cuántos clientes nuevos se captan cada mes?","Clientes con primera factura en cada mes.","SELECT SUBSTR(P.PRIMERA,1,7) AS MES, COUNT(*) AS NUEVOS FROM (SELECT CODCLIENTE, MIN(FECHA) AS PRIMERA FROM DOCCAB WHERE TIPO=13 GROUP BY CODCLIENTE) P WHERE P.PRIMERA >= DATE('now','-365 days') GROUP BY SUBSTR(P.PRIMERA,1,7) ORDER BY MES DESC","Marketing","Marketing","KPI","Alto","Captación",""),
    q("mx3_002","Tasa de retención de clientes anual","¿Qué porcentaje de clientes repite compra año a año?","Clientes que compraron el año anterior y también el actual.","SELECT COUNT(DISTINCT CASE WHEN SUBSTR(D.FECHA,1,4)=CAST(STRFTIME('%Y','now')-1 AS TEXT) THEN D.CODCLIENTE END) AS CLIENTES_ANTERIOR, COUNT(DISTINCT CASE WHEN SUBSTR(D.FECHA,1,4)=CAST(STRFTIME('%Y','now') AS TEXT) AND D.CODCLIENTE IN (SELECT DISTINCT CODCLIENTE FROM DOCCAB WHERE TIPO=13 AND SUBSTR(FECHA,1,4)=CAST(STRFTIME('%Y','now')-1 AS TEXT)) THEN D.CODCLIENTE END) AS RETENIDOS FROM DOCCAB D WHERE D.TIPO=13","Marketing","Marketing","KPI","Critico","Retención",""),
    q("mx3_003","Clientes perdidos en el último año","¿Qué clientes no han comprado en el último año?","Clientes con historial pero sin factura en 365 días.","SELECT D.CODCLIENTE, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, MAX(D.FECHA) AS ULTIMA_COMPRA, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VENTAS_HISTORICAS FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=13 GROUP BY D.CODCLIENTE, CLIENTE HAVING MAX(D.FECHA)<DATE('now','-365 days') ORDER BY VENTAS_HISTORICAS DESC LIMIT 20","Marketing","Marketing","Alerta","Alto","Churn",""),
    q("mx3_004","Ventas por zona geográfica (provincia)","¿Cómo se distribuyen las ventas por provincia?","Ventas agrupadas por provincia del cliente.","SELECT COALESCE(C.CP,'Sin provincia') AS PROVINCIA, COUNT(DISTINCT D.CODCLIENTE) AS N_CLIENTES, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VENTAS FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=13 GROUP BY COALESCE(C.CP,'Sin provincia') ORDER BY VENTAS DESC LIMIT 20","Marketing","Marketing","KPI","Alto","Geografía",""),
    q("mx3_005","Artículos más vendidos en el último trimestre","¿Qué artículos se venden más en el último trimestre?","Top artículos por unidades vendidas en los últimos 90 días.","SELECT L.CODARTICULO AS COD_ART, A.NOMBRE, ROUND(SUM(L.CANTIDAD),2) AS CANTIDAD, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=13 AND D.FECHA>=DATE('now','-90 days') GROUP BY L.CODARTICULO, A.NOMBRE ORDER BY CANTIDAD DESC LIMIT 20","Marketing","Marketing","KPI","Alto","Productos",""),
    q("mx3_006","Familias con mayor crecimiento de ventas","¿Qué familias crecen más en ventas?","Crecimiento de ventas por familia entre trimestre actual y anterior.","SELECT F.NOMBRE AS FAMILIA, ROUND(SUM(CASE WHEN D.FECHA>=DATE('now','-90 days') THEN L.CANTIDAD*L.PRECIO ELSE 0 END),2) AS VENTAS_ACTUAL, ROUND(SUM(CASE WHEN D.FECHA BETWEEN DATE('now','-180 days') AND DATE('now','-91 days') THEN L.CANTIDAD*L.PRECIO ELSE 0 END),2) AS VENTAS_ANTERIOR FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO LEFT JOIN FAMILIA F ON F.CODIGO=A.CODFAMILIA WHERE D.TIPO=13 AND D.FECHA>=DATE('now','-180 days') GROUP BY F.NOMBRE HAVING VENTAS_ACTUAL>VENTAS_ANTERIOR AND VENTAS_ANTERIOR>0 ORDER BY (VENTAS_ACTUAL-VENTAS_ANTERIOR) DESC LIMIT 15","Marketing","Marketing","KPI","Alto","Crecimiento",""),
    q("mx3_007","Clientes con mayor frecuencia de compra","¿Qué clientes compran con más frecuencia?","Clientes con mayor número de facturas en el último año.","SELECT D.CODCLIENTE, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, COUNT(DISTINCT D.CODIGO) AS N_FACTURAS, ROUND(SUM(L.CANTIDAD*L.PRECIO)/COUNT(DISTINCT D.CODIGO),2) AS TICKET_MEDIO FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=13 AND D.FECHA>=DATE('now','-365 days') GROUP BY D.CODCLIENTE, CLIENTE ORDER BY N_FACTURAS DESC LIMIT 20","Marketing","Marketing","KPI","Alto","Frecuencia",""),
    q("mx3_008","Presupuestos con mayor tasa de conversión por comercial","¿Qué comercial convierte más presupuestos en pedidos?","Tasa de conversión de presupuestos por usuario.","SELECT D.CODAGENTE, COUNT(DISTINCT D.CODIGO) AS N_PRESUPUESTOS, COUNT(DISTINCT D2.CODIGO) AS N_CONVERTIDOS, ROUND(COUNT(DISTINCT D2.CODIGO)*100.0/NULLIF(COUNT(DISTINCT D.CODIGO),0),1) AS TASA_PCT FROM DOCCAB D LEFT JOIN DOCCAB D2 ON 1=0 AND D2.TIPO=1 WHERE D.TIPO=2 GROUP BY D.CODAGENTE HAVING N_PRESUPUESTOS>0 ORDER BY TASA_PCT DESC LIMIT 15","Marketing","Marketing","KPI","Alto","Conversión",""),
    q("mx3_009","Artículos con mayor número de clientes distintos","¿Qué artículos tienen la base de clientes más amplia?","Artículos vendidos a más clientes distintos.","SELECT L.CODARTICULO AS COD_ART, A.NOMBRE, COUNT(DISTINCT D.CODCLIENTE) AS N_CLIENTES, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VENTAS FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=13 GROUP BY L.CODARTICULO, A.NOMBRE ORDER BY N_CLIENTES DESC LIMIT 20","Marketing","Marketing","KPI","Medio","Penetración",""),
    q("mx3_010","Ventas a clientes nuevos vs recurrentes por mes","¿Qué porcentaje de ventas proviene de clientes nuevos cada mes?","Ventas de clientes con primera compra en el mes vs recurrentes.","SELECT SUBSTR(D.FECHA,1,7) AS MES, ROUND(SUM(CASE WHEN PRIMERA.PRIMER_MES=SUBSTR(D.FECHA,1,7) THEN L.CANTIDAD*L.PRECIO ELSE 0 END),2) AS VENTAS_NUEVOS, ROUND(SUM(CASE WHEN PRIMERA.PRIMER_MES<SUBSTR(D.FECHA,1,7) THEN L.CANTIDAD*L.PRECIO ELSE 0 END),2) AS VENTAS_RECURRENTES FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO JOIN (SELECT CODCLIENTE, SUBSTR(MIN(FECHA),1,7) AS PRIMER_MES FROM DOCCAB WHERE TIPO=13 GROUP BY CODCLIENTE) PRIMERA ON PRIMERA.CODCLIENTE=D.CODCLIENTE WHERE D.TIPO=13 AND D.FECHA>=DATE('now','-365 days') GROUP BY SUBSTR(D.FECHA,1,7) ORDER BY MES DESC","Marketing","Marketing","KPI","Alto","Captación",""),
    q("mx3_011","Descuentos medios por familia de producto","¿Qué familias reciben más descuento en ventas?","Descuento medio aplicado por familia de artículo.","SELECT F.NOMBRE AS FAMILIA, ROUND(AVG(L.DESCUENTOS),2) AS DESCUENTO_MEDIO, COUNT(*) AS N_LINEAS FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO LEFT JOIN FAMILIA F ON F.CODIGO=A.CODFAMILIA WHERE D.TIPO=13 AND L.DESCUENTOS>0 GROUP BY F.NOMBRE ORDER BY DESCUENTO_MEDIO DESC LIMIT 15","Marketing","Marketing","KPI","Medio","Descuentos",""),
    q("mx3_012","Clientes con mayor potencial sin explotar","¿Qué clientes compran poco pero tienen historial de compras altas?","Clientes con ventas decrecientes en el último trimestre.","SELECT D.CODCLIENTE, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, ROUND(SUM(CASE WHEN D.FECHA>=DATE('now','-90 days') THEN L.CANTIDAD*L.PRECIO ELSE 0 END),2) AS VENTAS_RECIENTES, ROUND(SUM(CASE WHEN D.FECHA BETWEEN DATE('now','-365 days') AND DATE('now','-91 days') THEN L.CANTIDAD*L.PRECIO ELSE 0 END),2) AS VENTAS_ANTERIORES FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=13 AND D.FECHA>=DATE('now','-365 days') GROUP BY D.CODCLIENTE, CLIENTE HAVING VENTAS_RECIENTES<VENTAS_ANTERIORES*0.5 AND VENTAS_ANTERIORES>1000 ORDER BY VENTAS_ANTERIORES DESC LIMIT 15","Marketing","Marketing","Alerta","Alto","Potencial",""),
    q("mx3_013","Artículos con ventas estacionales marcadas","¿Qué artículos tienen ventas muy concentradas en ciertos meses?","Artículos con ventas en 3 o menos meses del año.","SELECT L.CODARTICULO AS COD_ART, A.NOMBRE, COUNT(DISTINCT SUBSTR(D.FECHA,1,7)) AS MESES_CON_VENTA, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VENTAS FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=13 AND D.FECHA>=DATE('now','-365 days') GROUP BY L.CODARTICULO, A.NOMBRE HAVING MESES_CON_VENTA<=3 AND VENTAS>500 ORDER BY VENTAS DESC LIMIT 20","Marketing","Marketing","KPI","Medio","Estacionalidad",""),
    q("mx3_014","Clientes que solo compran una familia de productos","¿Qué clientes están concentrados en una sola familia?","Clientes con compras en una única familia de artículos.","SELECT D.CODCLIENTE, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, COUNT(DISTINCT A.CODFAMILIA) AS N_FAMILIAS, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VENTAS FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=13 GROUP BY D.CODCLIENTE, CLIENTE HAVING N_FAMILIAS=1 ORDER BY VENTAS DESC LIMIT 20","Marketing","Marketing","KPI","Medio","Diversificación",""),
    q("mx3_015","Evolución del ticket medio por mes","¿Cómo evoluciona el ticket medio de venta mes a mes?","Importe medio por factura por mes.","SELECT SUBSTR(D.FECHA,1,7) AS MES, COUNT(DISTINCT D.CODIGO) AS N_FACTURAS, ROUND(SUM(L.CANTIDAD*L.PRECIO)/COUNT(DISTINCT D.CODIGO),2) AS TICKET_MEDIO FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=13 AND D.FECHA>=DATE('now','-365 days') GROUP BY SUBSTR(D.FECHA,1,7) ORDER BY MES DESC","Marketing","Marketing","KPI","Alto","Ticket medio",""),
    q("mx3_016","Artículos con mayor crecimiento de ventas interanual","¿Qué artículos crecen más en ventas respecto al año anterior?","Ventas del año actual vs año anterior por artículo.","SELECT L.CODARTICULO AS COD_ART, A.NOMBRE, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,4)=CAST(STRFTIME('%Y','now') AS TEXT) THEN L.CANTIDAD*L.PRECIO ELSE 0 END),2) AS VENTAS_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,4)=CAST(STRFTIME('%Y','now')-1 AS TEXT) THEN L.CANTIDAD*L.PRECIO ELSE 0 END),2) AS VENTAS_ANTERIOR FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=13 GROUP BY L.CODARTICULO, A.NOMBRE HAVING VENTAS_ACTUAL>VENTAS_ANTERIOR AND VENTAS_ANTERIOR>0 ORDER BY (VENTAS_ACTUAL-VENTAS_ANTERIOR) DESC LIMIT 20","Marketing","Marketing","KPI","Alto","Crecimiento",""),
    q("mx3_017","Clientes con mayor número de familias compradas","¿Qué clientes tienen la cartera de compras más diversificada?","Clientes con más familias distintas en sus facturas.","SELECT D.CODCLIENTE, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, COUNT(DISTINCT A.CODFAMILIA) AS N_FAMILIAS, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VENTAS FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=13 GROUP BY D.CODCLIENTE, CLIENTE ORDER BY N_FAMILIAS DESC LIMIT 20","Marketing","Marketing","KPI","Medio","Diversificación",""),
    q("mx3_018","Ventas por agente comercial","¿Cuánto vende cada agente comercial?","Ventas agrupadas por código de agente.","SELECT D.CODAGENTE, COUNT(DISTINCT D.CODCLIENTE) AS N_CLIENTES, COUNT(DISTINCT D.CODIGO) AS N_FACTURAS, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VENTAS FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=13 AND D.CODAGENTE IS NOT NULL GROUP BY D.CODAGENTE ORDER BY VENTAS DESC LIMIT 15","Marketing","Marketing","KPI","Alto","Agentes",""),
    q("mx3_019","Artículos nuevos con mayor adopción","¿Qué artículos nuevos han sido adoptados por más clientes?","Artículos con primera venta en el año actual y más clientes.","SELECT L.CODARTICULO AS COD_ART, A.NOMBRE, MIN(D.FECHA) AS PRIMERA_VENTA, COUNT(DISTINCT D.CODCLIENTE) AS N_CLIENTES, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VENTAS FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=13 GROUP BY L.CODARTICULO, A.NOMBRE HAVING MIN(D.FECHA)>=DATE('now','-180 days') ORDER BY N_CLIENTES DESC LIMIT 15","Marketing","Marketing","KPI","Alto","Innovación",""),
    q("mx3_020","Clientes con mayor LTV (valor de vida histórico)","¿Qué clientes tienen mayor valor histórico acumulado?","Ventas totales históricas por cliente.","SELECT D.CODCLIENTE, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, COUNT(DISTINCT D.CODIGO) AS N_FACTURAS, COUNT(DISTINCT SUBSTR(D.FECHA,1,4)) AS ANIOS_ACTIVO, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS LTV FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=13 GROUP BY D.CODCLIENTE, CLIENTE ORDER BY LTV DESC LIMIT 20","Marketing","Marketing","KPI","Critico","LTV",""),
    q("mx3_021","Ventas por forma de pago","¿Cómo se distribuyen las ventas por forma de pago?","Ventas agrupadas por forma de pago.","SELECT D.CODFORMAPAGO, COUNT(DISTINCT D.CODIGO) AS N_FACTURAS, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VENTAS FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=13 AND D.CODFORMAPAGO IS NOT NULL GROUP BY D.CODFORMAPAGO ORDER BY VENTAS DESC LIMIT 10","Marketing","Marketing","KPI","Medio","Formas de pago",""),
    q("mx3_022","Artículos con mayor margen y alta rotación","¿Qué artículos combinan alto margen y alta rotación?","Artículos con margen superior al 30% y más de 10 ventas.","SELECT L.CODARTICULO AS COD_ART, A.NOMBRE, COUNT(*) AS N_VENTAS, ROUND(AVG((L.PRECIO-A.PRECIOCOSTE)*100.0/NULLIF(L.PRECIO,0)),1) AS MARGEN_MEDIO_PCT FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=13 AND A.PRECIOCOSTE>0 AND L.PRECIO>0 GROUP BY L.CODARTICULO, A.NOMBRE HAVING N_VENTAS>10 AND MARGEN_MEDIO_PCT>30 ORDER BY MARGEN_MEDIO_PCT DESC LIMIT 20","Marketing","Marketing","KPI","Critico","Rentabilidad",""),
    q("mx3_023","Clientes sin compra en 60 días (riesgo abandono)","¿Qué clientes habituales no han comprado en 60 días?","Clientes con historial pero sin factura en 60 días.","SELECT D.CODCLIENTE, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, MAX(D.FECHA) AS ULTIMA_COMPRA, ROUND(JULIANDAY('now')-JULIANDAY(MAX(D.FECHA)),0) AS DIAS_SIN_COMPRA FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=13 GROUP BY D.CODCLIENTE, CLIENTE HAVING MAX(D.FECHA)<DATE('now','-60 days') AND SUM(L.CANTIDAD*L.PRECIO)>500 ORDER BY DIAS_SIN_COMPRA ASC LIMIT 20","Marketing","Marketing","Alerta","Alto","Churn",""),
    q("mx3_024","Presupuestos por cliente (pipeline de ventas)","¿Qué clientes tienen más presupuestos activos?","Presupuestos sin convertir en pedido por cliente.","SELECT D.CODCLIENTE, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, COUNT(DISTINCT D.CODIGO) AS N_PRESUPUESTOS, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VALOR_PIPELINE FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=2 AND D.CODIGO NOT IN (SELECT COALESCE(NULL,'') FROM DOCCAB WHERE TIPO=1) AND D.FECHA>=DATE('now','-90 days') GROUP BY D.CODCLIENTE, CLIENTE ORDER BY VALOR_PIPELINE DESC LIMIT 15","Marketing","Marketing","KPI","Alto","Pipeline",""),
    q("mx3_025","Ventas por tarifa de PRECIO aplicada","¿Qué tarifa de PRECIO se aplica más en ventas?","Ventas agrupadas por código de tarifa.","SELECT NULL, COUNT(DISTINCT D.CODIGO) AS N_FACTURAS, COUNT(DISTINCT D.CODCLIENTE) AS N_CLIENTES, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VENTAS FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=13 AND NULL IS NOT NULL GROUP BY 1 ORDER BY VENTAS DESC LIMIT 10","Marketing","Marketing","KPI","Medio","Tarifas",""),
    q("mx3_026","Artículos con mayor número de presupuestos","¿Qué artículos aparecen más en presupuestos?","Artículos con más líneas en presupuestos TIPO=2.","SELECT L.CODARTICULO AS COD_ART, A.NOMBRE, COUNT(*) AS N_PRESUPUESTOS, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VALOR_TOTAL FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=2 GROUP BY L.CODARTICULO, A.NOMBRE ORDER BY N_PRESUPUESTOS DESC LIMIT 20","Marketing","Marketing","KPI","Medio","Presupuestos",""),
    q("mx3_027","Clientes con mayor número de presupuestos rechazados","¿Qué clientes rechazan más presupuestos?","Clientes con presupuestos sin convertir en pedido.","SELECT D.CODCLIENTE, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, COUNT(DISTINCT D.CODIGO) AS N_PRESUPUESTOS_RECHAZADOS FROM DOCCAB D LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=2 AND D.CODIGO NOT IN (SELECT COALESCE(NULL,'') FROM DOCCAB WHERE TIPO=1) GROUP BY D.CODCLIENTE, CLIENTE ORDER BY N_PRESUPUESTOS_RECHAZADOS DESC LIMIT 15","Marketing","Marketing","KPI","Medio","Conversión",""),
    q("mx3_028","Ventas por código postal (top zonas)","¿Qué códigos postales generan más ventas?","Ventas agrupadas por código postal del cliente.","SELECT COALESCE(C.CP,'Sin CP') AS CP, COUNT(DISTINCT D.CODCLIENTE) AS N_CLIENTES, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VENTAS FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=13 GROUP BY COALESCE(C.CP,'Sin CP') ORDER BY VENTAS DESC LIMIT 20","Marketing","Marketing","KPI","Medio","Geografía",""),
    q("mx3_029","Artículos con mayor tasa de descuento aplicado","¿En qué artículos se aplican más descuentos?","Artículos con mayor descuento medio en facturas.","SELECT L.CODARTICULO AS COD_ART, A.NOMBRE, COUNT(*) AS N_LINEAS, ROUND(AVG(L.DESCUENTOS),2) AS DESCUENTO_MEDIO FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=13 AND L.DESCUENTOS>0 GROUP BY L.CODARTICULO, A.NOMBRE ORDER BY DESCUENTO_MEDIO DESC LIMIT 20","Marketing","Marketing","KPI","Medio","Descuentos",""),
    q("mx3_030","Clientes con compras en todas las familias","¿Qué clientes compran de todas las familias disponibles?","Clientes con artículos de todas las familias del catálogo.","SELECT D.CODCLIENTE, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, COUNT(DISTINCT A.CODFAMILIA) AS N_FAMILIAS FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=13 GROUP BY D.CODCLIENTE, CLIENTE HAVING N_FAMILIAS=(SELECT COUNT(*) FROM FAMILIA) ORDER BY N_FAMILIAS DESC LIMIT 10","Marketing","Marketing","KPI","Bajo","Diversificación",""),
    q("mx3_031","Evolución de presupuestos emitidos por mes","¿Cuántos presupuestos se emiten cada mes?","Presupuestos TIPO=2 agrupados por mes.","SELECT SUBSTR(D.FECHA,1,7) AS MES, COUNT(*) AS N_PRESUPUESTOS, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VALOR_TOTAL FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=2 AND D.FECHA>=DATE('now','-365 days') GROUP BY SUBSTR(D.FECHA,1,7) ORDER BY MES DESC","Marketing","Marketing","KPI","Alto","Presupuestos",""),
    q("mx3_032","Clientes con mayor número de artículos distintos comprados","¿Qué clientes compran más variedad de artículos?","Artículos distintos por cliente en el último año.","SELECT D.CODCLIENTE, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, COUNT(DISTINCT L.CODARTICULO) AS N_ARTICULOS, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VENTAS FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=13 AND D.FECHA>=DATE('now','-365 days') GROUP BY D.CODCLIENTE, CLIENTE ORDER BY N_ARTICULOS DESC LIMIT 20","Marketing","Marketing","KPI","Medio","Diversificación",""),
    q("mx3_033","Ventas a clientes extranjeros por país","¿Cuánto se vende a cada país extranjero?","Ventas a clientes con país distinto a España.","SELECT COALESCE(C.CODPAIS,'Sin país') AS CODPAIS, COUNT(DISTINCT D.CODCLIENTE) AS N_CLIENTES, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VENTAS FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=13 AND C.CODPAIS IS NOT NULL AND C.CODPAIS<>'ES' GROUP BY COALESCE(C.CODPAIS,'Sin país') ORDER BY VENTAS DESC LIMIT 20","Marketing","Marketing","KPI","Alto","Exportación",""),
    q("mx3_034","Artículos con ventas crecientes 3 meses consecutivos","¿Qué artículos llevan 3 meses con ventas crecientes?","Artículos con ventas mayores cada mes en los últimos 3 meses.","SELECT L.CODARTICULO AS COD_ART, A.NOMBRE, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,7)=STRFTIME('%Y-%m','now') THEN L.CANTIDAD*L.PRECIO ELSE 0 END),2) AS MES3, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,7)=STRFTIME('%Y-%m',DATE('now','-1 month')) THEN L.CANTIDAD*L.PRECIO ELSE 0 END),2) AS MES2, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,7)=STRFTIME('%Y-%m',DATE('now','-2 months')) THEN L.CANTIDAD*L.PRECIO ELSE 0 END),2) AS MES1 FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=13 AND D.FECHA>=DATE('now','-90 days') GROUP BY L.CODARTICULO, A.NOMBRE HAVING MES3>MES2 AND MES2>MES1 AND MES1>0 ORDER BY MES3 DESC LIMIT 15","Marketing","Marketing","KPI","Alto","Tendencia",""),
    q("mx3_035","Clientes con mayor importe de presupuestos activos","¿Qué clientes tienen más valor en presupuestos activos?","Valor de presupuestos sin convertir por cliente.","SELECT D.CODCLIENTE, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, COUNT(DISTINCT D.CODIGO) AS N_PRESUPUESTOS, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VALOR FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=2 AND D.CODIGO NOT IN (SELECT COALESCE(NULL,'') FROM DOCCAB WHERE TIPO=1) GROUP BY D.CODCLIENTE, CLIENTE ORDER BY VALOR DESC LIMIT 15","Marketing","Marketing","KPI","Alto","Pipeline",""),
    q("mx3_036","Familias con mayor número de clientes compradores","¿Qué familias tienen más clientes distintos?","Clientes distintos por familia de artículo.","SELECT F.NOMBRE AS FAMILIA, COUNT(DISTINCT D.CODCLIENTE) AS N_CLIENTES, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VENTAS FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO LEFT JOIN FAMILIA F ON F.CODIGO=A.CODFAMILIA WHERE D.TIPO=13 GROUP BY F.NOMBRE ORDER BY N_CLIENTES DESC LIMIT 15","Marketing","Marketing","KPI","Alto","Penetración",""),
    q("mx3_037","Artículos con mayor importe de presupuestos","¿Qué artículos aparecen con más valor en presupuestos?","Artículos con mayor importe total en presupuestos TIPO=2.","SELECT L.CODARTICULO AS COD_ART, A.NOMBRE, COUNT(*) AS N_PRESUPUESTOS, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VALOR_TOTAL FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=2 GROUP BY L.CODARTICULO, A.NOMBRE ORDER BY VALOR_TOTAL DESC LIMIT 20","Marketing","Marketing","KPI","Medio","Presupuestos",""),
    q("mx3_038","Clientes con mayor crecimiento interanual","¿Qué clientes crecen más en ventas respecto al año anterior?","Crecimiento de ventas por cliente año actual vs anterior.","SELECT D.CODCLIENTE, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,4)=CAST(STRFTIME('%Y','now') AS TEXT) THEN L.CANTIDAD*L.PRECIO ELSE 0 END),2) AS VENTAS_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,4)=CAST(STRFTIME('%Y','now')-1 AS TEXT) THEN L.CANTIDAD*L.PRECIO ELSE 0 END),2) AS VENTAS_ANTERIOR FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=13 GROUP BY D.CODCLIENTE, CLIENTE HAVING VENTAS_ACTUAL>VENTAS_ANTERIOR AND VENTAS_ANTERIOR>0 ORDER BY (VENTAS_ACTUAL-VENTAS_ANTERIOR) DESC LIMIT 15","Marketing","Marketing","KPI","Alto","Crecimiento",""),
    q("mx3_039","Ventas por sector de cliente","¿Cómo se distribuyen las ventas por sector de cliente?","Ventas agrupadas por familia de cliente.","SELECT COALESCE(NULL,'Sin sector') AS SECTOR, COUNT(DISTINCT D.CODCLIENTE) AS N_CLIENTES, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VENTAS FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=13 GROUP BY COALESCE(NULL,'Sin sector') ORDER BY VENTAS DESC LIMIT 15","Marketing","Marketing","KPI","Alto","Segmentación",""),
    q("mx3_040","Artículos con mayor número de pedidos de venta","¿Qué artículos aparecen en más pedidos de venta?","Artículos con más líneas en pedidos TIPO=1.","SELECT L.CODARTICULO AS COD_ART, A.NOMBRE, COUNT(DISTINCT L.CODDOCUMENTO) AS N_PEDIDOS, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VALOR FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=1 GROUP BY L.CODARTICULO, A.NOMBRE ORDER BY N_PEDIDOS DESC LIMIT 20","Marketing","Marketing","KPI","Medio","Demanda",""),
    q("mx3_041","Clientes con mayor número de pedidos activos","¿Qué clientes tienen más pedidos pendientes de servir?","Clientes con más pedidos TIPO=1 sin albarán.","SELECT D.CODCLIENTE, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, COUNT(DISTINCT D.CODIGO) AS N_PEDIDOS, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VALOR FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=1 AND D.CODIGO NOT IN (SELECT COALESCE(NULL,'') FROM DOCCAB WHERE TIPO=11) GROUP BY D.CODCLIENTE, CLIENTE ORDER BY N_PEDIDOS DESC LIMIT 15","Marketing","Marketing","KPI","Alto","Backlog",""),
    q("mx3_042","Ventas por día de la semana","¿Qué días de la semana se vende más?","Ventas agrupadas por día de la semana.","SELECT STRFTIME('%w',D.FECHA) AS DIA_NUM, CASE STRFTIME('%w',D.FECHA) WHEN '1' THEN 'Lunes' WHEN '2' THEN 'Martes' WHEN '3' THEN 'Miércoles' WHEN '4' THEN 'Jueves' WHEN '5' THEN 'Viernes' ELSE 'Fin de semana' END AS DIA, COUNT(DISTINCT D.CODIGO) AS N_FACTURAS, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VENTAS FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=13 AND D.FECHA IS NOT NULL GROUP BY STRFTIME('%w',D.FECHA) ORDER BY DIA_NUM","Marketing","Marketing","KPI","Bajo","Actividad",""),
    q("mx3_043","Artículos con mayor número de devoluciones","¿Qué artículos generan más devoluciones?","Artículos con más líneas en abonos TIPO=14.","SELECT L.CODARTICULO AS COD_ART, A.NOMBRE, COUNT(*) AS N_DEVOLUCIONES, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS IMPORTE_DEVUELTO FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=14 GROUP BY L.CODARTICULO, A.NOMBRE ORDER BY N_DEVOLUCIONES DESC LIMIT 20","Marketing","Marketing","Alerta","Alto","Devoluciones",""),
    q("mx3_044","Clientes con mayor importe de devoluciones","¿Qué clientes devuelven más mercancía?","Clientes con mayor importe en abonos TIPO=14.","SELECT D.CODCLIENTE, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, COUNT(DISTINCT D.CODIGO) AS N_ABONOS, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS IMPORTE_DEVUELTO FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=14 GROUP BY D.CODCLIENTE, CLIENTE ORDER BY IMPORTE_DEVUELTO DESC LIMIT 15","Marketing","Marketing","Alerta","Alto","Devoluciones",""),
    q("mx3_045","Resumen de KPIs de marketing del mes","¿Cuáles son los KPIs de marketing del mes actual?","Clientes activos, nuevos, ventas y presupuestos del mes.","SELECT (SELECT COUNT(DISTINCT D.CODCLIENTE) FROM DOCCAB D WHERE D.TIPO=13 AND SUBSTR(D.FECHA,1,7)=STRFTIME('%Y-%m','now')) AS CLIENTES_ACTIVOS_MES, (SELECT COUNT(*) FROM DOCCAB D WHERE D.TIPO=2 AND SUBSTR(D.FECHA,1,7)=STRFTIME('%Y-%m','now')) AS PRESUPUESTOS_MES, (SELECT ROUND(SUM(L.CANTIDAD*L.PRECIO),2) FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO WHERE D.TIPO=13 AND SUBSTR(D.FECHA,1,7)=STRFTIME('%Y-%m','now')) AS VENTAS_MES","Marketing","Marketing","KPI","Critico","Resumen",""),
    q("mx3_046","Artículos con mayor penetración en clientes nuevos","¿Qué artículos compran más los clientes nuevos?","Artículos más vendidos a clientes con primera compra en el año.","SELECT L.CODARTICULO AS COD_ART, A.NOMBRE, COUNT(DISTINCT D.CODCLIENTE) AS N_CLIENTES_NUEVOS, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS VENTAS FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=13 AND D.CODCLIENTE IN (SELECT CODCLIENTE FROM DOCCAB WHERE TIPO=13 GROUP BY CODCLIENTE HAVING MIN(FECHA)>=DATE('now','-365 days')) GROUP BY L.CODARTICULO, A.NOMBRE ORDER BY N_CLIENTES_NUEVOS DESC LIMIT 15","Marketing","Marketing","KPI","Alto","Captación",""),
    q("mx3_047","Clientes con mayor número de referencias compradas en el año","¿Qué clientes compran más referencias distintas en el año?","Referencias distintas por cliente en el año actual.","SELECT D.CODCLIENTE, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, COUNT(DISTINCT L.CODARTICULO) AS N_REFERENCIAS FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=13 AND SUBSTR(D.FECHA,1,4)=CAST(STRFTIME('%Y','now') AS TEXT) GROUP BY D.CODCLIENTE, CLIENTE ORDER BY N_REFERENCIAS DESC LIMIT 20","Marketing","Marketing","KPI","Medio","Diversificación",""),
    q("mx3_048","Ventas por NULL (directo vs con albarán)","¿Qué NULL de venta genera más facturación?","Facturas agrupadas por si tienen albarán previo o son directas.","SELECT CASE WHEN D.CODALMACENORIGEN IS NOT NULL AND D.CODALMACENORIGEN > 0 THEN 'Con albarán' ELSE 'Directo' END AS NULL, COUNT(DISTINCT D.CODIGO) AS N_FACTURAS, CAST(SUM(L.CANTIDAD*L.PRECIO) AS NUMERIC(15,2)) AS VENTAS FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=13 GROUP BY CASE WHEN D.CODALMACENORIGEN IS NOT NULL AND D.CODALMACENORIGEN > 0 THEN 'Con albarán' ELSE 'Directo' END ORDER BY VENTAS DESC","Marketing","Marketing","KPI","Alto","NULL",""),
    q("mx3_049","Artículos con mayor ratio ventas/presupuestos","¿Qué artículos tienen mejor conversión de presupuesto a venta?","Ratio entre ventas y presupuestos por artículo.","SELECT FIRST 20 L.CODARTICULO AS COD_ART, A.NOMBRE, CAST(SUM(CASE WHEN D.TIPO=13 THEN L.CANTIDAD*L.PRECIO ELSE 0 END) AS NUMERIC(15,2)) AS VENTAS, CAST(SUM(CASE WHEN D.TIPO=2 THEN L.CANTIDAD*L.PRECIO ELSE 0 END) AS NUMERIC(15,2)) AS PRESUPUESTADO FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO IN (2,13) GROUP BY L.CODARTICULO, A.NOMBRE HAVING SUM(CASE WHEN D.TIPO=2 THEN L.CANTIDAD*L.PRECIO ELSE 0 END)>0 ORDER BY SUM(CASE WHEN D.TIPO=13 THEN L.CANTIDAD*L.PRECIO ELSE 0 END)/SUM(CASE WHEN D.TIPO=2 THEN L.CANTIDAD*L.PRECIO ELSE 0 END) DESC","Marketing","Marketing","KPI","Medio","Conversión",""),
    q("mx3_050","Resumen anual de marketing","¿Cuál es el resumen anual de marketing?","Métricas anuales: clientes, ventas, presupuestos, conversión.","SELECT CAST(STRFTIME('%Y','now') AS TEXT) AS EJERCICIO, (SELECT COUNT(DISTINCT CODCLIENTE) FROM DOCCAB WHERE TIPO=13 AND SUBSTR(FECHA,1,4)=CAST(STRFTIME('%Y','now') AS TEXT)) AS CLIENTES_ACTIVOS, (SELECT COUNT(*) FROM DOCCAB WHERE TIPO=2 AND SUBSTR(FECHA,1,4)=CAST(STRFTIME('%Y','now') AS TEXT)) AS PRESUPUESTOS_EMITIDOS, (SELECT ROUND(SUM(L.CANTIDAD*L.PRECIO),2) FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO WHERE D.TIPO=13 AND SUBSTR(D.FECHA,1,4)=CAST(STRFTIME('%Y','now') AS TEXT)) AS VENTAS_TOTALES","Marketing","Marketing","KPI","Critico","Resumen",""),
]
